"""Local photo atlas; inferred layout and raw camera positions are separate layers."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'field-review/guanghua-lawn-survey-v1'
data=json.loads((OUT/'survey.json').read_text(encoding='utf-8'))
template=r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>光华楼草坪 · 照片地图</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f1e9;color:#243f3b;font:15px/1.65 "Microsoft YaHei",system-ui,sans-serif}header{padding:23px 30px 17px;border-bottom:1px solid #ced5ca;background:#fcfbf6}h1{margin:0;font-size:25px;letter-spacing:1px;font-weight:600}.eyebrow{font-size:11px;letter-spacing:3px;color:#6c7c6a}header p{margin:5px 0 0;color:#64716a;font-size:13px}a{color:#14655c}header a{float:right;margin-top:7px;padding:8px 14px;border:1px solid #99b3a7;border-radius:5px;text-decoration:none}main{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(310px,1fr);gap:20px;padding:20px 25px;max-width:1600px;margin:auto}.map-wrap{min-width:0}.toolbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:0 0 12px}select,button,input{font:inherit}select,button{padding:7px 10px;background:#fffef9;border:1px solid #c1cbbf;border-radius:4px;color:#284b42}button{cursor:pointer}button:hover{background:#e5eadf}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #bc7434;outline-offset:2px}label{font-size:12px;color:#55695c}#map{width:100%;display:block;background:#e8edde;border-radius:8px;border:1px solid #cad5c2;touch-action:manipulation}#map text{font-family:"Microsoft YaHei",sans-serif}.base-label{font-size:12px;fill:#435952;letter-spacing:1px}.pin{cursor:pointer}.pin circle{fill:#f9f6e9;stroke:#496e5a;stroke-width:1.3}.pin text{font-size:11px;fill:#284b42;font-weight:bold}.pin.active circle{fill:#9e522e;stroke:#fff9df;stroke-width:2}.pin.active text{fill:white}.photo-dot{fill:#337995;opacity:.55}.note{font-size:12px;color:#6a7267;margin:9px 0}.legend{display:flex;flex-wrap:wrap;gap:16px;font-size:12px;margin-top:10px}.legend span:before{content:"";display:inline-block;width:10px;height:10px;margin-right:5px;vertical-align:middle;background:#377f9c;border-radius:50%}.legend span:nth-child(2):before{background:#c5d6a7;border:1px solid #678357;border-radius:0}.legend span:nth-child(3):before{background:#9e522e}.photo-pane{min-width:0;padding:0 0 15px}#photo{width:100%;max-height:430px;object-fit:contain;background:#233e39;display:block;border-radius:7px}.photo-top{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:9px}h2{font-size:17px;line-height:1.5;margin:0}#meta{font-size:12px;color:#5f7067;margin:9px 0}.caption{background:#e7eadf;padding:11px 13px;border-left:3px solid #849d69;font-size:13px;margin-top:12px}#timeline{width:100%;accent-color:#387761}.timeline-label{display:flex;justify-content:space-between;font-size:12px;color:#52675c}.nav{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:13px}.thumbs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:15px}.thumbs button{padding:0;overflow:hidden;border:2px solid transparent;background:#e6eadd;font-size:11px;line-height:1.5}.thumbs button.selected{border-color:#a46331}.thumbs img{width:100%;height:68px;object-fit:cover;display:block}.tag{font-size:11px;color:#866235}.links{margin-top:15px;font-size:12px;display:flex;gap:15px;flex-wrap:wrap}#count{font-size:12px}.error{color:#a03621}@media(max-width:900px){main{grid-template-columns:1fr;padding:14px}header{padding:18px}header a{float:none;display:inline-block;margin:9px 0 0}h1{font-size:22px}#photo{max-height:500px}}@media(max-width:450px){.toolbar{align-items:stretch}.toolbar select{width:100%}.thumbs img{height:57px}}
</style></head><body>
<header><a href="locations.html">地点目录 / 精修入口 ↗</a><div class="eyebrow">FUDAN / FIELD SURVEY 01</div><h1>光华楼前 · 照片地图</h1><p>305 张现场照片 · 15 段行走路线 · 21 个主要地点 · 2026.09.27</p></header>
<main><section class="map-wrap"><div class="toolbar"><select id="zone" aria-label="按路线浏览"><option value="all">全部照片 · 按拍摄顺序</option></select><label><input type="checkbox" id="route" checked> 拍摄轨迹</label><label><input type="checkbox" id="points" checked> 拍摄点</label><button id="clear">返回全部</button></div>
<svg id="map" viewBox="0 0 900 690" role="img" aria-label="光华楼草坪推定平面与拍摄位置，楼在上方。"><defs><pattern id="grid" width="16" height="16" patternUnits="userSpaceOnUse"><rect width="16" height="16" fill="#d9d6c9"/><path d="M16 0H0V16" fill="none" stroke="#efecdd" stroke-width="1.8"/></pattern></defs><g id="base"></g><g id="track"></g><g id="dots"></g><g id="pins"></g><g id="current"></g></svg>
<div class="legend"><span>蓝点：手机拍摄位置</span><span>绿地 / 路径：推定布局</span><span>棕色：当前选择</span></div>
<p class="note">点击地点编号查看证据照片，点击蓝点查看该次拍摄。虚线圆是照片记录的 GPS 误差范围；箭头为手机记录朝向。地图朝向：光华楼在上方。</p>
<p class="note">尺寸、台阶标高、园路曲线与被树木遮挡的部分仍需校正。GPS 坐标未吸附到道路，也不代表镜头中对象的精确位置。</p>
</section><section class="photo-pane"><div class="photo-top"><h2 id="title"></h2><a id="original" target="_blank" rel="noopener">查看原图 ↗</a></div><img id="photo" alt="当前现场照片"><div id="meta"></div><div class="timeline-label"><span id="time"></span><span id="count"></span></div><input id="timeline" type="range" min="0" max="304" value="162" aria-label="按时间浏览当前照片组"><div class="nav"><button id="prev">← 上一张</button><span id="scope" class="tag"></span><button id="next">下一张 →</button></div><div class="caption" id="caption"></div><div class="thumbs" id="thumbs"></div><div class="links"><a href="viewer.html">三维模型</a><a href="README.md">范围与推定说明</a><a href="survey.json">定位与证据数据</a><a href="model/guanghua-lawn-v1.blend">Blender 场景</a><a href="model/guanghua-lawn-v1.glb">GLB 场景</a></div></section></main>
<script>
const D=__DATA__;
const $=id=>document.getElementById(id),X=x=>(x+103)*4,Y=y=>(156-y)*4;
const svg=(tag,attrs={},text='')=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));n.textContent=text;return n;};
const line=(pts,attrs)=>svg('polyline',{points:pts.map(([x,y])=>`${X(x)},${Y(y)}`).join(' '),fill:'none',...attrs});
const rect=(x,y,w,h,attrs)=>svg('rect',{x:X(x),y:Y(y+h),width:w*4,height:h*4,...attrs});
const base=$('base');
base.append(rect(-89,-8,9,137,{fill:'#a8afab'}),rect(109,-8,9,137,{fill:'#a8afab'}),rect(-89,-8,207,9,{fill:'#a8afab'}));
base.append(rect(-80,1,189,111,{fill:'#cbd8b5'}),rect(-80,87,189,26,{fill:'url(#grid)'}));
base.append(svg('path',{d:`M${X(-25)} ${Y(16)}H${X(70)}V${Y(81)}Q${X(70)} ${Y(88)} ${X(63)} ${Y(88)}H${X(-18)}Q${X(-25)} ${Y(88)} ${X(-25)} ${Y(81)}Z`,fill:'#a4bd7c',stroke:'#7d9765','stroke-width':1}));
base.append(rect(-75,117,188,25,{fill:'#b5bbb5',stroke:'#838d85'}),rect(-14,139,29,12,{fill:'#869890'}),rect(34,139,29,12,{fill:'#869890'}));
for(let y=109;y<117;y+=1.6)base.append(rect(-39,y,116,1.1,{fill:'#c2c4b9'}));
D.paths.forEach(p=>base.append(line(p.points,{stroke:'#b6b0a0','stroke-width':p.width*4+2,'stroke-linejoin':'round','stroke-linecap':'round'})));
D.paths.forEach(p=>base.append(line(p.points,{stroke:p.id.includes('inner')?'#e2decd':'#dfcfae','stroke-width':p.width*4,'stroke-linejoin':'round','stroke-linecap':'round'})));
base.append(rect(-74,43,23,28,{fill:'#d4c8b2',stroke:'#746b55','stroke-width':1.5}),rect(84,43,17,23,{fill:'#d4c8b2',stroke:'#867f64'}));
[[90,48,11,1.2],[88,52,12,1.2],[87,56,13,1.2]].forEach(r=>base.append(rect(...r,{fill:'#aaa68d'})));
base.append(line([[110,19],[101,22],[95,28],[94,39]],{stroke:'#9a9a8d','stroke-width':27,'stroke-linejoin':'round'}));
for(let y=22;y<40;y+=2.8)base.append(line([[90,y],[99,y]],{stroke:'#685e45','stroke-width':2}));
for(const [x,y] of [[-62,51],[-62,63],[-34,43],[-56,83],[-61,83],[83,45]]){base.append(rect(x-2.5,y-2.5,5,5,{fill:'#a9c5c4',stroke:'#608780'}));base.append(line([[x-2.5,y-2.5],[x+2.5,y+2.5]],{stroke:'#5c7776','stroke-width':1}));}
for(const f of D.features.filter(f=>f.type==='opening')){const [x,y]=f.xy;base.append(rect(x-2,y-2,4,4,{fill:'#667168',stroke:'#e5e7d4','stroke-width':2}));}
for(const [x,y,w,h] of [[-59,4,7,6],[-75,26,6,5],[-81,45,10,6],[-81,67,10,6]])base.append(rect(x,y,w,h,{fill:'#afbdb2',stroke:'#5c7668'}));
for(const [x,y,t] of [[20,130,'光华楼 / 建筑参照'],[23,55,'主 草 坪'],[22,99,'北侧铺装广场'],[-61,35,'西花园'],[93,84,'东花园'],[20,-4,'南侧道路'],[-85,105,'西路'],[114,105,'东路']]){const a={'x':X(x),'y':Y(y),'text-anchor':'middle',class:'base-label'};if(t==='西路'||t==='东路')a.transform=`rotate(-90 ${X(x)} ${Y(y)})`;base.append(svg('text',a,t));}
base.append(svg('text',{x:18,y:27,class:'base-label'},'比例推定 · 非实测平面'));base.append(svg('text',{x:18,y:47,class:'base-label'},'编号对应构筑物 / 拍摄点保留原 GPS'));
base.append(svg('path',{d:'M850 68L862 29M862 29L853 36M862 29L865 40',fill:'none',stroke:'#425f50','stroke-width':2}),svg('text',{x:840,y:87,class:'base-label'},'真北≈'));
let selection=D.photos.slice(),index=D.photos.findIndex(p=>p.number===4474),feature=null;
D.zones.forEach(z=>{const o=document.createElement('option');o.value=z.id;o.textContent=`${z.id} · ${z.name} (${z.count})`;$('zone').append(o);});
const pins=new Map();D.features.forEach((f,i)=>{const g=svg('g',{class:'pin','data-id':f.id});g.append(svg('circle',{cx:X(f.xy[0]),cy:Y(f.xy[1]),r:10}),svg('text',{x:X(f.xy[0]),y:Y(f.xy[1])+4,'text-anchor':'middle'},String(i+1).padStart(2,'0')));g.append(svg('title',{},`${i+1} ${f.name}`));g.onclick=()=>{feature=f;selection=f.photos.map(n=>D.photos.find(p=>p.number===n));index=0;$('zone').value='all';update();};$('pins').append(g);pins.set(f.id,g);});
function updateMap(){
 const p=selection[index],shown=new Set(selection.map(q=>q.number));$('track').replaceChildren();$('dots').replaceChildren();$('current').replaceChildren();
 if($('route').checked){$('track').append(line(D.photos.map(p=>[p.x,p.y]),{stroke:'#277799','stroke-width':1,opacity:.35,'stroke-dasharray':'3 3'}));}
 if($('points').checked)D.photos.forEach(q=>{const c=svg('circle',{cx:X(q.x),cy:Y(q.y),r:shown.has(q.number)?2.7:1.8,class:'photo-dot',opacity:shown.has(q.number)?.75:.2});c.onclick=()=>{if(!shown.has(q.number)){feature=null;selection=D.photos.slice();$('zone').value='all';}index=selection.findIndex(a=>a.number===q.number);update();};$('dots').append(c);});
 pins.forEach((g,id)=>g.setAttribute('class',`pin${feature?.id===id?' active':''}`));
 const h=p.local_heading*Math.PI/180,cx=X(p.x),cy=Y(p.y),r=(p.gps_error_m||14)*4;
 $('current').append(svg('circle',{cx,cy,r,fill:'#b17f37','fill-opacity':.08,stroke:'#a57837','stroke-width':1.4,'stroke-dasharray':'5 4','pointer-events':'none'}));
 $('current').append(svg('path',{d:`M${cx},${cy} l${Math.sin(h-.38)*35},${-Math.cos(h-.38)*35} A35,35 0 0,1 ${cx+Math.sin(h+.38)*35},${cy-Math.cos(h+.38)*35} Z`,fill:'#b06939','fill-opacity':.35,'pointer-events':'none'}));
 $('current').append(svg('circle',{cx,cy,r:5,fill:'#ab572e',stroke:'#fff8e7','stroke-width':2,'pointer-events':'none'}));
}
function update(){const p=selection[index],z=D.zones.find(z=>z.id===p.zone);$('photo').src='thumbs/'+p.file;$('photo').alt=`${p.file} · ${p.zone_name}`;$('original').href='../../references/guanghua_lawn/img/img/'+p.file;$('title').textContent=feature?feature.name:p.zone_name;$('meta').textContent=`${p.file} · 第 ${p.sequence} / 305 张 · ${p.zone} · GPS 误差约 ${(p.gps_error_m||0).toFixed(1)} m`;$('time').textContent=p.time.slice(-8)+' (+08:00)';$('count').textContent=`当前组 ${index+1} / ${selection.length}`;$('timeline').max=selection.length-1;$('timeline').value=index;$('scope').textContent=feature?'已筛选地点证据':$('zone').value==='all'?'全部照片':z.name;$('caption').textContent=feature?`${feature.name}：存在由现场照片确认，位置和尺寸为推定。当前显示 ${feature.photos.length} 张相关证据。`:`${z.description}。此组按拍摄顺序和画面内容归区；局部细节的精确对象对应仍可进一步细分。`;$('prev').disabled=index===0;$('next').disabled=index===selection.length-1;
 let nearby=feature?selection:selection.slice(Math.max(0,Math.min(index-3,selection.length-8)),Math.max(8,index+5));nearby=nearby.slice(0,8);$('thumbs').replaceChildren();nearby.forEach(q=>{const b=document.createElement('button');b.className=q.number===p.number?'selected':'';const im=document.createElement('img');im.src='thumbs/'+q.file;im.alt='';b.append(im,document.createTextNode(q.file.replace('IMG_','').replace('.jpeg','')));b.onclick=()=>{index=selection.findIndex(a=>a.number===q.number);update();};$('thumbs').append(b);});updateMap();}
$('zone').onchange=()=>{feature=null;selection=$('zone').value==='all'?D.photos.slice():D.photos.filter(p=>p.zone===$('zone').value);index=0;update();};$('clear').onclick=()=>{$('zone').value='all';$('zone').onchange();};$('prev').onclick=()=>{index=Math.max(0,index-1);update();};$('next').onclick=()=>{index=Math.min(selection.length-1,index+1);update();};$('timeline').oninput=e=>{index=+e.target.value;update();};$('route').onchange=updateMap;$('points').onchange=updateMap;document.addEventListener('keydown',e=>{if(['SELECT','INPUT'].includes(e.target.tagName))return;if(e.key==='ArrowLeft')$('prev').click();if(e.key==='ArrowRight')$('next').click();});function applyHash(){const linked=D.features.find(f=>f.id===decodeURIComponent(location.hash.slice(1)));if(linked){feature=linked;selection=linked.photos.map(n=>D.photos.find(p=>p.number===n));index=0;}update();}window.addEventListener('hashchange',applyHash);applyHash();
</script></body></html>'''
(OUT/'index.html').write_text(template.replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':'))),encoding='utf-8')
print('Wrote atlas:',OUT/'index.html')
